import{z as l,x as s,o as e,c as d,q as n,j as i,D as E,d as r,s as o,S as A,b as B}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"障碍结构的组合","description":"","frontmatter":{"title":"障碍结构的组合","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ot-barrier-portfolios.md","filePath":"quant/ot-barrier-portfolios.md","lastUpdated":1791063341000}'),m={name:"quant/ot-barrier-portfolios.md"};function p(h,a,u,D,f,C){const t=s("Mermaid");return e(),d("div",null,[a[2]||(a[2]=n('<h1 id="障碍结构的组合" tabindex="-1">障碍结构的组合 <a class="header-anchor" href="#障碍结构的组合" aria-label="Permalink to &quot;障碍结构的组合&quot;">​</a></h1><div class="epigraph"><p>障碍不是一种期权，是一根轴：敲入与敲出在轴上互补，触碰与数字在轴上取值；账本上的风险问的不是单笔头寸，而是同一根轴上还挂着谁。</p><footer>—— 据 Derman, Ergener and Kani, Journal of Derivatives, 1995；Broadie, Glasserman and Kou, Mathematical Finance, 1997 整理</footer></div><p><a href="/quant/ot-fcn">上一课</a>把 FCN 的风险收进一条向下敲入看跌，产品解剖里雪球与 FCN 的公共骨架至此露出来：障碍。本课不再按产品走，把障碍当成组合件——敲入与敲出的互补、触碰与数字的取值、账本上同一水平线的堆积如何聚合。单笔障碍的希腊在障碍前不连续，这是<a href="/quant/vt-exotic-risk-map">奇异风控地图</a>立过的；本课把视角移到账本层，后课的发行方对冲默认以这张聚合地图为输入。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单笔障碍的定价与对冲，主干已有<a href="/quant/barrier-analytics">障碍解析</a>与<a href="/quant/barrier-monitoring">监控频率</a>；剩下的缺口在组合层。发行台同时挂着几十份条款各异的障碍：卖给客户的敲出、从对手买回的敲入、雪球账本里嵌着的两道线、FCN 里的保护垫。每笔单独看都在限额内，加总却可能互相放大——同一标的两笔头寸的障碍线只差 \\(1\\%\\)、观察时钟一个收盘一个盘中，账面上近似对消，风险上并不对消。缺口因此是两个：组合恒等式在什么条件下成立；不成立的部分怎么计量。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>第一条是代数。同一标的、同一期限、同一行权价、同一监控约定下，敲入与敲出互补：</p> \\[V_{\\mathrm{KI}}+V_{\\mathrm{KO}}=V_{\\mathrm{vanilla}}. \\]<p>触碰结构在轴上取值：one-touch 是「只要触碰付一元」的美式数字，no-touch 是它的互补；数字障碍把触碰与支付量乘在一起。账本聚合按三元组分桶：标的、障碍水平、观察时钟。桶内加总净敞口，桶间只有当时钟一致、水平可视为同一带时才承认对消——<a href="/quant/snowball-dealer-hedging">对冲商的堆积</a>用的正是这套分桶，只是那里加总到市场层，这里止于账本层。</p><p><span class="marginnote">术语翻译：敲入与敲出是一枚硬币的两面——标的「碰到过障碍」与「从没碰到」必居其一。所以同一规格的敲入加敲出，恰好拼回一张不带障碍的普通期权。恒等式看似免费，前提是两边按同一套时钟观察触碰。</span></p><p>第二条是静态复制。Derman、Ergener 与 Kani 表明：用香草期权条带可以在到期前的每个日期把障碍价值钉住，条带随时间衰减、需要在既定日期滚动；Carr、Ellis 与 Gupta 把单障碍的静态组合做成有限条香草加数字。静态条带给出的不是免费对冲，是一张到期日与行权价受限的近似——场内没有任意行权价时，残差回到账本。</p><p><span class="marginnote">Broadie–Glasserman–Kou 的平移量按 \\(\\exp(\\pm 0.5826\\,\\sigma\\sqrt{\\Delta t})\\) 缩放：收盘观察与盘中观察之间，同一根名义障碍线对应的连续等价障碍可以差出可观的距离。KI 与 KO 的恒等式只在两边共享同一监控约定时成立；一边收盘一边盘中，代数恒等式变成两条不同的平移线之间的残差。</span></p><p><span class="marginnote">数字实例：年化波动 20%、按日观察时，BGK 平移约 \\(0.5826\\times0.2\\times\\sqrt{1/252}\\approx0.73\\%\\)——名义敲入线 90%，连续等价线其实在 89.3% 附近。换成盘中观察，这一差还要再放大；账本若按名义线布置对冲，就带着系统性错位过每个观察日。</span></p>',13)),(e(),i(A,null,{default:E(()=>[o(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20BK%5B%22%E8%B4%A6%E6%9C%AC%E9%9A%9C%E7%A2%8D%E5%A4%B4%E5%AF%B8%22%5D%20--%3E%20B1%5B%22%E6%8C%89%E6%A0%87%E7%9A%84%E3%80%81%E6%B0%B4%E5%B9%B3%E3%80%81%E6%97%B6%E9%92%9F%E5%88%86%E6%A1%B6%22%5D%0A%20%20B1%20--%3E%20AGG%5B%22%E6%A1%B6%E5%86%85%E5%8A%A0%E6%80%BB%E5%87%80%E6%95%9E%E5%8F%A3%22%5D%0A%20%20CLOCK%5B%22%E6%97%B6%E9%92%9F%E4%B8%80%E8%87%B4%EF%BC%9F%E6%B0%B4%E5%B9%B3%E5%90%8C%E5%B8%A6%EF%BC%9F%22%5D%20--%3E%20NET%5B%22%E6%89%BF%E8%AE%A4%E5%AF%B9%E6%B6%88%EF%BC%9A%E5%87%80%E9%A2%9D%E6%A1%B6%22%5D%0A%20%20CLOCK%20--%3E%7C%E5%90%A6%7C%20RES%5B%22%E4%B8%8D%E6%89%BF%E8%AE%A4%E5%AF%B9%E6%B6%88%EF%BC%9A%E6%AE%8B%E5%B7%AE%E6%A1%B6%22%5D%0A%20%20AGG%20--%3E%20NET%0A%20%20NET%20--%3E%20MAP%5B%22%E9%9A%9C%E7%A2%8D%E6%9A%B4%E9%9C%B2%E5%9C%B0%E5%9B%BE%EF%BC%9A%E4%BE%9B%E7%BB%99%E4%B8%8E%E7%BC%BA%E5%8F%A3%22%5D%0A%20%20RES%20--%3E%20MAP%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[r("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"恒等式成立的条件比恒等式本身重要。KI 加 KO 等于香草，是路径集合划分的恒等式：触碰与不触碰把样本空间切成两半。条件一，监控约定相同——划分必须切在同一个事件上；条件二，对手方可以同时履约——账面对消是风险的，法律上两笔头寸是两个对手的债权，一笔违约不减免另一笔。把组合对消当信用对消，是场外账本最贵的一类错误，ISDA 的净额集与法律构造是下一课的缺口。",-1)),(e(),i(A,null,{default:E(()=>[o(t,{id:"mermaid-42",class:"mermaid",graph:"flowchart%20TD%0A%20%20KI%5B%22%E5%90%91%E5%AF%B9%E6%89%8BA%E4%B9%B0%E5%85%A5%E6%95%B2%E5%85%A5%22%5D%20--%3E%20P%5B%22%E8%B4%A6%E9%9D%A2%E5%87%80%E6%95%9E%E5%8F%A3%E8%BF%91%E4%BC%BC%E4%B8%BA%E9%9B%B6%22%5D%0A%20%20KO%5B%22%E5%90%91%E5%AF%B9%E6%89%8BB%E5%8D%96%E5%87%BA%E6%95%B2%E5%87%BA%22%5D%20--%3E%20P%0A%20%20P%20--%3E%20Q%7B%22%E5%AF%B9%E6%89%8BA%E8%BF%9D%E7%BA%A6%3F%22%7D%0A%20%20Q%20--%3E%7C%22%E5%90%A6%22%7C%20OK%5B%22%E4%B8%A4%E8%85%BF%E7%BB%A7%E7%BB%AD%E4%BA%92%E6%8A%B5%22%5D%0A%20%20Q%20--%3E%7C%22%E6%98%AF%22%7C%20L1%5B%22%E6%95%B2%E5%85%A5%E8%85%BF%E4%BF%9D%E6%8A%A4%E6%B6%88%E5%A4%B1%22%5D%0A%20%20L1%20--%3E%20EXP%5B%22%E6%95%B2%E5%87%BA%E8%85%BF%E4%B9%89%E5%8A%A1%E4%BB%8D%E8%A6%81%E5%B1%A5%E7%BA%A6%22%5D%0A%20%20EXP%20--%3E%20NET%5B%22%E8%B4%A6%E9%9D%A2%E5%AF%B9%E6%B6%88%E4%B8%8D%E7%AD%89%E4%BA%8E%E6%B3%95%E5%BE%8B%E5%87%80%E9%A2%9D%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p>静态复制的机制价值在于把「障碍不可对冲」的宿命论拆开：障碍的连续暴露可以用有限条香草分段钉住，代价是条带的维护与滚动。发行台因此有两条腿：动态对冲管理连续暴露，静态条带管理不连续点附近的暴露带——<a href="/quant/vt-product-hedging">波动率产品的对冲</a>的 delta 手册在此延伸到障碍层。不这么做会错在哪：只用动态对冲，观察日前gamma 的峰值把对冲流量打满；只用静态条带，场内行权价间隔留下的残差没人认领。</p><p><span class="marginnote">常见误区：以为「静态复制」就是买好一篮子香草放着不管。条带价值随时间衰减，必须在既定日期滚动；场内没有恰好合用的行权价时，残差还得回到账本认领——「静态」说的是组合不逐日重估，不是免维护。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推障碍闭式与 BGK 平移的推导，监控约定的定价后果沿<a href="/quant/barrier-monitoring">监控频率</a>；把聚合地图外推成市场供给曲线是<a href="/quant/snowball-dealer-hedging">对冲商的堆积</a>的主题，本课不越界。窗口障碍、软障碍与重置障碍只报条款名，不逐一定价。对消的法律边界、对手信用折价，都推给下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>敲入与敲出在相同监控约定下互补：\\(V_{\\mathrm{KI}}+V_{\\mathrm{KO}}=V_{\\mathrm{vanilla}}\\)，恒等式的价值在成立条件。</li><li>账本按标的、障碍水平、观察时钟分桶聚合；时钟不一致或水平不同带，对消不成立。</li><li>静态复制用香草条带钉住障碍的分段价值，滚动与行权价受限是残差的来源。</li><li>组合对消不等于信用对消：对手不同，法律上没有净额。</li><li>出处：Derman, Ergener and Kani, <em>Journal of Derivatives</em>, 1995；Carr, Ellis and Gupta, 1998；Broadie, Glasserman and Kou, <em>Mathematical Finance</em>, 1997。</li></ul>',6))])}const _=l(m,[["render",p]]);export{F as __pageData,_ as default};
